import { useMemo, useRef, useState } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Breadcrumb, type BreadcrumbItem } from "@registry/aikoz/breadcrumb/breadcrumb";
import { BarChart } from "@registry/aikoz/bar-chart/bar-chart";
import { Button } from "@registry/aikoz/button/button";
import { EmptyState } from "@registry/aikoz/empty-state/empty-state";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ZoneGeo {
  id: string;
  /** Nom affiché — « Île-de-France », « Rhône ». */
  label: string;
  /** Valeur mesurée sur la zone. */
  value: number;
  /** Zones filles. Absent ou vide = on ne peut pas forer plus bas. */
  children?: ZoneGeo[];
}

export interface GeoDrilldownProps {
  /** Nom de la racine — « France » en général. */
  rootLabel: string;
  /** Premier niveau : les régions. */
  zones: ZoneGeo[];
  /** Ce que la valeur mesure, **unité comprise** — « Avis reçus », « Taux (%) ». */
  valueLabel: string;
  formatValue?: (v: number) => string;
  /** Prévenu à chaque changement de niveau, avec le chemin complet. */
  onNavigate?: (chemin: ZoneGeo[]) => void;
  height?: number;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Forage géographique — `France > Région > Département`.
 *
 * **Ce n'est pas une carte, et c'est délibéré.** L'inventaire notait que le
 * Figma ne contient aucun tracé géographique, seulement des étiquettes de
 * région. Une carte choroplèthe aurait par ailleurs trois défauts ici : elle
 * encode la valeur par une teinte sur des surfaces de tailles très inégales
 * (la Lozère et le Nord pèsent pareil à l'œil), elle demande un fond de carte
 * à tenir à jour, et elle ne se lit pas du tout au lecteur d'écran. Une barre
 * horizontale compare des longueurs — ce que l'œil fait le mieux — et se
 * double d'un tableau.
 *
 * **Le forage ne passe PAS par le clic sur les barres.** Le graphique est
 * `aria-hidden` (cf. `ChartFrame`) : y mettre la seule commande de navigation
 * la rendrait inatteignable au clavier et invisible à un lecteur d'écran. Le
 * bouton « Explorer » vit donc dans le **tableau**, qui est le contenu réel.
 * Le clic sur une barre reste offert en plus, comme raccourci à la souris.
 *
 * Le fil d'Ariane remonte. Il utilise `onClick` et non `href` : on ne change
 * pas d'URL, et annoncer un lien qui n'en est pas un tromperait.
 */
export function GeoDrilldown({
  rootLabel,
  zones,
  valueLabel,
  formatValue = (v) => v.toLocaleString("fr-FR"),
  onNavigate,
  height = 320,
  className,
}: GeoDrilldownProps) {
  const [chemin, setChemin] = useState<ZoneGeo[]>([]);
  // L'annonce du changement de niveau : sans elle, un lecteur d'écran voit le
  // tableau se réécrire sans savoir pourquoi.
  const [annonce, setAnnonce] = useState("");
  const ancre = useRef<HTMLDivElement | null>(null);

  const niveau = chemin.length === 0 ? zones : (chemin[chemin.length - 1].children ?? []);

  const aller = (suite: ZoneGeo[]) => {
    setChemin(suite);
    const zonesSuivantes = suite.length === 0 ? zones : (suite[suite.length - 1].children ?? []);
    const nom = suite.length === 0 ? rootLabel : suite[suite.length - 1].label;
    setAnnonce(`${nom} — ${zonesSuivantes.length} zone${zonesSuivantes.length > 1 ? "s" : ""}.`);
    onNavigate?.(suite);
    // Le focus suit le forage : la commande qu'on vient d'actionner disparaît
    // du document avec l'ancien niveau. Sans reprise, il retombe sur `body`.
    requestAnimationFrame(() => ancre.current?.focus());
  };

  const fil: BreadcrumbItem[] = [
    { label: rootLabel, onClick: chemin.length ? () => aller([]) : undefined },
    ...chemin.map((z, i) => ({
      label: z.label,
      onClick: i < chemin.length - 1 ? () => aller(chemin.slice(0, i + 1)) : undefined,
    })),
  ];

  const data = useMemo(
    () => niveau.map((z) => ({ zone: z.label, valeur: z.value, id: z.id })),
    [niveau]
  );

  const zoneParLabel = useMemo(
    () => new Map(niveau.map((z) => [z.label, z])),
    [niveau]
  );

  const titre = chemin.length === 0 ? rootLabel : chemin[chemin.length - 1].label;

  return (
    <div className={cn("flex flex-col gap-4", className)}>
      <Breadcrumb items={fil} label="Niveau géographique" />

      {/* `tabIndex={-1}` : cible de focus après un forage, jamais dans la
          tabulation. */}
      <div ref={ancre} tabIndex={-1} className="outline-none">
        {/* Région live : c'est elle qui dit qu'on a changé de niveau. */}
        <p role="status" aria-live="polite" className="sr-only">
          {annonce}
        </p>

        {niveau.length === 0 ? (
          <EmptyState
            density="compact"
            title={`Aucune donnée sous ${titre}`}
            description="Ce niveau ne se décompose pas davantage."
          />
        ) : (
          <BarChart
            caption={`${valueLabel} — ${titre}`}
            data={data}
            xKey="zone"
            xLabel="Zone"
            yLabel={valueLabel}
            orientation="horizontal"
            series={[{ key: "valeur", label: valueLabel }]}
            formatValue={(v) => formatValue(Number(v))}
            height={height}
            tableau="dessous"
            onBarClick={(ligne: Record<string, string | number>) => {
              const z = zoneParLabel.get(String(ligne.zone));
              if (z?.children?.length) aller([...chemin, z]);
            }}
            extraColumns={[
              {
                key: "explorer",
                header: "Détail",
                cell: (ligne: Record<string, string | number>) => {
                  const z = zoneParLabel.get(String(ligne.zone));
                  if (!z?.children?.length) {
                    return (
                      <span className="text-xs text-muted-foreground">
                        Dernier niveau
                      </span>
                    );
                  }
                  return (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => aller([...chemin, z])}
                    >
                      {/* Le nom de la zone est DANS le bouton, en `sr-only` :
                          sans lui, un lecteur d'écran qui liste les commandes
                          entend « Explorer » huit fois de suite. */}
                      Explorer
                      <span className="sr-only"> {z.label}</span>
                    </Button>
                  );
                },
              },
            ]}
          />
        )}
      </div>
    </div>
  );
}

import { Fragment, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface BreadcrumbItem {
  label: string;
  /** Absent sur le dernier élément : la page courante n'est pas un lien. */
  href?: string;
  /**
   * Remonte d'un niveau **sans changer d'URL** — cas d'un forage dans une
   * même vue (`GeoDrilldown`). Un `<button>` est alors rendu à la place du
   * lien : ce n'est pas une navigation, et l'annoncer comme telle tromperait.
   * Ignoré si `href` est fourni.
   */
  onClick?: () => void;
  /** Icône décorative — une maison sur la racine, en général. */
  icon?: ReactNode;
}

export interface BreadcrumbProps {
  items: BreadcrumbItem[];
  /** Nom du `<nav>`. « Fil d'Ariane » par défaut. */
  label?: string;
  /**
   * Séparateur. Toujours `aria-hidden` : il est visuel. La structure est
   * portée par la liste ordonnée, que les lecteurs d'écran annoncent déjà
   * « liste de 4 éléments, élément 3 ».
   */
  separator?: ReactNode;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Fil d'Ariane.
 *
 * Un `<nav>` nommé, une `<ol>` — l'ordre porte du sens, ce n'est pas une
 * `<ul>` —, et **le dernier élément n'est pas un lien**. C'est la faute la
 * plus courante du motif : rendre la page courante cliquable produit un lien
 * qui ne mène nulle part, et prive `aria-current="page"` de son support.
 *
 * Le séparateur est décoratif et masqué. Un « / » lu à voix haute entre
 * chaque niveau n'apporte rien : la liste ordonnée dit déjà la profondeur.
 *
 * **Ce composant ne replie pas les niveaux intermédiaires.** Un fil trop long
 * pour sa largeur passe à la ligne. Le repli en « … » est une bonne idée sur
 * un site profond, mais il masque des niveaux à tout le monde pour un
 * problème de place, et il demande son propre contrat clavier — ce sera une
 * variante explicite le jour où une arborescence le justifie.
 */
export function Breadcrumb({
  items,
  label = "Fil d'Ariane",
  separator = "/",
  className,
}: BreadcrumbProps) {
  return (
    <nav aria-label={label} className={className}>
      <ol className="flex flex-wrap items-center gap-1.5 list-none m-0 p-0 text-sm">
        {items.map((item, i) => {
          const dernier = i === items.length - 1;
          const contenu = (
            <>
              {item.icon && (
                <span aria-hidden="true" className="inline-flex shrink-0 [&>svg]:size-4">
                  {item.icon}
                </span>
              )}
              {item.label}
            </>
          );

          return (
            <Fragment key={`${item.label}-${i}`}>
              <li className="inline-flex items-center">
                {!dernier && item.onClick && !item.href ? (
                  <button
                    type="button"
                    onClick={item.onClick}
                    className={cn(
                      "inline-flex items-center gap-1.5 rounded-[calc(var(--radius)/2)]",
                      // Même soulignement au repos que le lien : c'est le seul
                      // signe qu'on peut agir dessus, et la couleur seule ne
                      // suffit pas (WCAG 1.4.1).
                      "text-muted-foreground underline underline-offset-2",
                      "hover:text-foreground",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                      "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
                    )}
                  >
                    {contenu}
                  </button>
                ) : dernier || !item.href ? (
                  <span
                    // `aria-current="page"` sur un `<span>`, pas sur un lien :
                    // c'est ce qui dit « vous êtes ici » sans promettre une
                    // navigation qui n'aura pas lieu.
                    aria-current={dernier ? "page" : undefined}
                    className={cn(
                      "inline-flex items-center gap-1.5",
                      dernier
                        ? "font-medium text-foreground"
                        : "text-muted-foreground"
                    )}
                  >
                    {contenu}
                  </span>
                ) : (
                  <a
                    href={item.href}
                    className={cn(
                      "inline-flex items-center gap-1.5 rounded-[calc(var(--radius)/2)]",
                      // Le soulignement est là AU REPOS, pas seulement au
                      // survol : dans un fil d'Ariane rien d'autre ne
                      // distingue un lien d'un simple mot, et la couleur
                      // seule ne suffit pas (WCAG 1.4.1).
                      "text-muted-foreground underline underline-offset-2",
                      "hover:text-foreground",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                      "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
                    )}
                  >
                    {contenu}
                  </a>
                )}
              </li>
              {!dernier && (
                <li aria-hidden="true" className="text-muted-foreground select-none">
                  {separator}
                </li>
              )}
            </Fragment>
          );
        })}
      </ol>
    </nav>
  );
}

import {
  Bar,
  CartesianGrid,
  Label,
  BarChart as RechartsBarChart,
  ResponsiveContainer,
  Tooltip as RechartsTooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  ChartFrame,
  ChartTooltipContent,
  opaciteSerie,
  couleurSerie,
  type ChartSerie,
} from "@registry/aikoz/chart-frame/chart-frame";
import { useId } from "react";
import { type TableColumn } from "@registry/aikoz/table/table";

/**
 * Le sommet d'une barre, arrondi ; sa base, franche.
 *
 * Arrondir les quatre coins ferait flotter la barre au-dessus de l'axe alors
 * qu'elle en part : la base est une mesure, pas une décoration. C'est le tracé
 * commun aux tableaux de bord récents, et il ne change rien à la LONGUEUR —
 * le rayon se prend à l'intérieur, la hauteur reste proportionnelle.
 *
 * Le rayon se borne à la moitié de la largeur ET à la hauteur : sur une barre
 * plus courte que son rayon, un arrondi non borné produit un tracé qui se
 * replie sur lui-même.
 */
function cheminBarre(x: number, y: number, w: number, h: number, r: number) {
  const rayon = Math.max(0, Math.min(r, w / 2, h));
  if (rayon === 0) return `M${x},${y}h${w}v${h}h${-w}Z`;
  return (
    `M${x},${y + h}` +
    `V${y + rayon}` +
    `a${rayon},${rayon} 0 0 1 ${rayon},${-rayon}` +
    `h${w - 2 * rayon}` +
    `a${rayon},${rayon} 0 0 1 ${rayon},${rayon}` +
    `V${y + h}` +
    `Z`
  );
}

// ─── Ticks d'axe ──────────────────────────────────────────────────────────────

/**
 * Chiffres à chasse fixe sur les graduations.
 *
 * Mesuré : en Gotham, les dix chiffres proportionnels s'étalent sur 35,7 px de
 * large — un axe vertical dont les valeurs ne s'alignent pas verticalement.
 * Gotham EMBARQUE les chiffres tabulaires (écart mesuré 0 une fois la variante
 * demandée) ; il manquait seulement de les demander. Même constat en Montserrat
 * (30,2) et en Inter (23,9).
 *
 * Hoisté plutôt que recopié : la variante avait été oubliée sur une des cinq
 * déclarations de ticks du module parce qu'elles étaient écrites à la main.
 *
 * `style` et non une propriété de premier niveau : recharts type l'objet `tick`
 * en `SVGProps<SVGTextElement>`, qui ne connaît pas `fontVariantNumeric` —
 * la propriété CSS passe par `style`, qui est bien dans le typage.
 */
const CHIFFRES_ALIGNES = { fontVariantNumeric: "tabular-nums" } as const;

const TICK = {
  fill: "var(--muted-foreground)",
  fontSize: 12,
  style: CHIFFRES_ALIGNES,
} as const;

// ─── Types ────────────────────────────────────────────────────────────────────

export interface BarChartProps {
  caption: string;
  data: Array<Record<string, string | number>>;
  xKey: string;
  series: ChartSerie[];
  /**
   * `stacked` empile les séries — pour une composition dont le TOTAL compte.
   * `grouped` les juxtapose — pour comparer les séries entre elles.
   * `stacked-percent` empile, mais chaque barre est ramenée à 100 % de son
   * propre total — pour comparer une RÉPARTITION d'une catégorie à l'autre
   * (ex. polarité positif/négatif par segment), où le total de chaque barre
   * n'a justement pas à être comparable. Chaque part porte son pourcentage
   * écrit, et les catégories passent en en-têtes au-dessus des barres — cf.
   * la note du composant.
   *
   * Ce n'est pas un réglage d'apparence : empilé, on lit bien le total mais
   * mal chaque part, sauf la première qui seule part de zéro. Groupé, on
   * compare les parts mais on perd le total. Le choix dépend de la question
   * posée, pas de la place disponible.
   */
  layout?: "stacked" | "grouped" | "stacked-percent";
  /** Barres horizontales — indispensable quand les libellés sont longs. */
  orientation?: "vertical" | "horizontal";
  /**
   * Nom de l'axe des catégories, **unité comprise**. Rendu sur le graphique
   * ET repris en en-tête du tableau.
   */
  xLabel?: string;
  /**
   * Nom de l'axe des valeurs, **unité comprise** — « Avis reçus »,
   * « Part (%) ». Carbon est explicite : un axe quantitatif sans unité laisse
   * le lecteur deviner ce qu'il compte.
   */
  yLabel?: string;
  formatValue?: (v: string | number) => string;
  height?: number;
  /**
   * Colonnes ajoutées au tableau équivalent, après les séries. Sert à y poser
   * une COMMANDE — le graphique étant `aria-hidden`, le tableau est le seul
   * endroit où une action reste atteignable au clavier.
   */
  extraColumns?: TableColumn<Record<string, string | number>>[];
  /**
   * Clic sur une barre. **Raccourci à la souris uniquement** : le graphique
   * est masqué aux technologies d'assistance, donc toute action offerte ici
   * doit aussi exister dans le tableau, via `extraColumns`.
   */
  onBarClick?: (ligne: Record<string, string | number>) => void;
  /** Déplie le tableau équivalent au lieu de le replier dans un `details`. */
  /**
   * Comment le tableau équivalent cohabite avec le graphique — voir
   * `ChartFrame`. `"bascule"` par défaut : deux vues du même bloc, à hauteur
   * constante.
   */
  tableau?: "bascule" | "dessous";
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Barres empilées ou groupées.
 *
 * **Le second canal d'une barre n'est pas un pointillé mais une TRAME** :
 * un aplat n'a pas de tracé où poser des tirets. Hachures, points,
 * quadrillage — même rôle, même ordre fixe que les tracés des courbes, de
 * sorte qu'une série garde son identité d'un type de graphique à l'autre.
 *
 * **Un séparateur clair entre les segments empilés.** Deux séries adjacentes
 * dont les teintes se ressemblent — et la palette garantit qu'il y en aura —
 * fusionneraient en un seul bloc. Le trait de 2 px à la couleur de la carte
 * les sépare sans ajouter de couleur.
 *
 * Le reste du contrat — graphique masqué, tableau comme contenu, légende en
 * tête, aucune animation — vient de `ChartFrame`.
 */
export function BarChart({
  caption,
  data,
  xKey,
  series,
  layout = "stacked",
  orientation = "vertical",
  xLabel,
  yLabel,
  extraColumns,
  onBarClick,
  tableau = "bascule",
  formatValue = (v) => String(v),
  height = 300,
  className,
}: BarChartProps) {
  const horizontal = orientation === "horizontal";
  // Les dégradés vivent dans le SVG du graphique : sans identifiant unique,
  // deux histogrammes sur la même page partageraient leurs `<linearGradient>`
  // et le second reprendrait les couleurs du premier.
  const idDegrade = useId().replace(/:/g, "");
  const percent = layout === "stacked-percent";
  const empile = layout === "stacked" || percent;

  const columns: TableColumn<Record<string, string | number>>[] = [
    { key: xKey, header: xLabel ?? "Catégorie" },
    ...series.map((s) => ({
      key: s.key,
      header: s.label,
      numeric: true,
      cell: (row: Record<string, string | number>) => formatValue(row[s.key]),
    })),
    ...(extraColumns ?? []),
  ];

  // En empilé, le total est l'information principale : il a sa colonne. En
  // pourcentage aussi — c'est justement ce que le graphique NE montre pas
  // (chaque barre est ramenée à 100 %), donc le tableau reste le seul endroit
  // où le volume réel de chaque catégorie est lisible.
  if (empile && series.length > 1) {
    columns.push({
      key: "__total",
      header: "Total",
      numeric: true,
      cell: (row) =>
        formatValue(series.reduce((t, s) => t + Number(row[s.key] ?? 0), 0)),
    });
  }

  // Données du GRAPHIQUE en pourcentage — le tableau, lui, garde les valeurs
  // réelles ci-dessus : c'est le seul endroit où le volume par catégorie
  // reste lisible une fois la barre ramenée à 100 %.
  const chartData = percent
    ? data.map((row) => {
        const total = series.reduce((t, s) => t + Number(row[s.key] ?? 0), 0);
        const next: Record<string, string | number> = { ...row };
        for (const s of series) {
          next[s.key] = total ? (Number(row[s.key] ?? 0) / total) * 100 : 0;
        }
        return next;
      })
    : data;

  // L'accord suit le nombre de séries : « 1 série groupée », pas « groupées ».
  const pluriel = series.length > 1 ? "s" : "";
  const resume =
    `${caption}. ${series.length} série${pluriel} ` +
    `${percent ? "ramenée" + pluriel + " à 100 % par catégorie" : empile ? "empilée" + pluriel : "groupée" + pluriel} ` +
    `sur ${data.length} catégorie${data.length > 1 ? "s" : ""}.`;

  return (
    <ChartFrame
      caption={caption}
      summary={resume}
      series={series}
      data={data}
      columns={columns}
      getRowKey={(row) => String(row[xKey])}
      rowHeaderKey={xKey}
      height={height}
      legendStyle="aplat"
      tableau={tableau}
      className={className}
    >
      {({ infobulleActive, indexActif, surSurvol }) => (
        <ResponsiveContainer width="100%" height="100%">
          <RechartsBarChart
            data={chartData}
            layout={horizontal ? "vertical" : "horizontal"}
            // `tabIndex={-1}` : recharts rend son SVG focusable par défaut.
            // Dans un sous-arbre `aria-hidden`, un élément focusable est une
            // contradiction — axe la signale (aria-hidden-focus), et c'en est
            // une vraie : le focus y entrerait sans que rien ne soit annoncé.
            tabIndex={-1}
            margin={{ top: percent && !horizontal ? 28 : 8, right: 8, bottom: 8, left: 0 }}
            // `cursor: pointer` en style inline : recharts pose son propre
            // `cursor: default` sur son `.recharts-wrapper`, qu'une classe
            // héritée ne peut pas battre.
            style={{ cursor: "pointer" }}
            onMouseMove={surSurvol}
            onMouseLeave={() => surSurvol(null)}
          >
            <defs>
              {/* Un dégradé par série, dense à la BASE et nominal au sommet.
                  La barre paraît ainsi partir de l'axe au lieu d'y être posée.

                  Le sens n'est pas indifférent : la couleur nominale reste le
                  point le plus CLAIR de la barre, donc tous les contrastes déjà
                  audités — l'étiquette de pourcentage au centre du segment, la
                  série contre la carte — restent des bornes basses. Éclaircir
                  le sommet les aurait invalidés d'un coup. */}
              {series.map((s, i) => (
                <linearGradient
                  key={s.key}
                  id={`${idDegrade}-s${i}`}
                  x1="0"
                  y1="1"
                  x2="0"
                  y2="0"
                >
                  <stop
                    offset="0%"
                    stopColor={`color-mix(in oklch, ${couleurSerie(i)}, black 16%)`}
                  />
                  <stop offset="100%" stopColor={couleurSerie(i)} />
                </linearGradient>
              ))}
            </defs>
            {infobulleActive && (
              <RechartsTooltip
                content={<ChartTooltipContent formatValue={(v) => formatValue(v)} />}
                // Le voile de survol de recharts assombrit toute la colonne.
                // `--surface-hover` est le token prévu pour ça ; un noir à 10 %
                // ne suivrait pas le thème.
                cursor={{ fill: "var(--surface-hover)" }}
                isAnimationActive={false}
              />
            )}
            <CartesianGrid
              stroke="var(--border)"
              strokeDasharray="3 3"
              vertical={horizontal}
              horizontal={!horizontal}
            />
            {horizontal ? (
              <>
                // Graduations en chiffres tabulaires : sur un axe vertical, des chiffres
            // de chasse variable décalent les graduations les unes par rapport aux
            // autres et le rail de gauche ondule.
            <XAxis
                  type="number"
                  domain={percent ? [0, 100] : undefined}
                  ticks={percent ? [0, 50, 100] : undefined}
                  tickFormatter={percent ? (v) => `${v} %` : undefined}
                  tick={TICK}
                  stroke="var(--border-strong)"
                  tickLine={false}
                  height={yLabel ? 44 : 30}
                >
                  {/* En disposition couchée, c'est l'axe HORIZONTAL qui porte
                      les valeurs : `yLabel` le nomme, pas `xLabel`. */}
                  {yLabel && (
                    <Label
                      value={yLabel}
                      position="insideBottom"
                      offset={-2}
                      fill="var(--muted-foreground)"
                      fontSize={12}
                    />
                  )}
                </XAxis>
                <YAxis
                  type="category"
                  dataKey={xKey}
                  // Largeur DÉDUITE du libellé le plus long, pas figée à
                  // 120px : « Auvergne-Rhône-Alpes » s'y faisait rogner à
                  // gauche, et « Provence-Alpes-Côte d'Azur » passait à la
                  // ligne. Une barre couchée sert justement à loger des
                  // libellés longs — les tronquer lui retire sa raison d'être.
                  // Bornée à 260px pour ne pas écraser la zone de tracé.
                  width={Math.min(
                    260,
                    Math.max(
                      96,
                      Math.max(...chartData.map((d) => String(d[xKey] ?? "").length)) * 7 + 16
                    )
                  )}
                  tick={TICK}
                  stroke="var(--border-strong)"
                  tickLine={false}
                />
              </>
            ) : (
              <>
                <XAxis
                  dataKey={xKey}
                  // En pourcentage, la catégorie devient un en-tête DE
                  // COHORTE au-dessus de sa barre — pas un repère d'axe : on
                  // veut la voir avant même de lire la barre, comme un titre
                  // de colonne. `orientation="top"`, trait masqué, graisse
                  // relevée sur `--foreground` plutôt que le gris habituel
                  // des ticks d'axe.
                  orientation={percent ? "top" : "bottom"}
                  axisLine={!percent}
                  tick={
                    percent
                      ? { ...TICK, fill: "var(--foreground)", fontSize: 13, fontWeight: 600 }
                      : TICK
                  }
                  stroke="var(--border-strong)"
                  tickLine={false}
                  height={xLabel && !percent ? 44 : 30}
                >
                  {/* En pourcentage la catégorie passe EN HAUT, comme un
                      en-tête de cohorte : y ajouter un nom d'axe sous les
                      barres pointerait vers des ticks qui n'y sont plus. */}
                  {xLabel && !percent && (
                    <Label
                      value={xLabel}
                      position="insideBottom"
                      offset={-2}
                      fill="var(--muted-foreground)"
                      fontSize={12}
                    />
                  )}
                </XAxis>
                <YAxis
                  width={yLabel ? 60 : 44}
                  domain={percent ? [0, 100] : undefined}
                  ticks={percent ? [0, 50, 100] : undefined}
                  tickFormatter={percent ? (v) => `${v} %` : undefined}
                  tick={TICK}
                  stroke="var(--border-strong)"
                  tickLine={false}
                >
                  {yLabel && (
                    <Label
                      value={yLabel}
                      angle={-90}
                      position="insideLeft"
                      style={{ textAnchor: "middle" }}
                      fill="var(--muted-foreground)"
                      fontSize={12}
                    />
                  )}
                </YAxis>
              </>
            )}
            {series.map((s, i) => (
              <Bar
                key={s.key}
                dataKey={s.key}
                onClick={onBarClick ? (_, index) => onBarClick(chartData[index]) : undefined}
                style={onBarClick ? { cursor: "pointer" } : undefined}
                // `name` : sans lui l'infobulle affiche la CLÉ de la série
                // (« pj ») au lieu de son libellé (« Pages Jaunes »).
                name={s.label}
                stackId={empile ? "pile" : undefined}
                fill={couleurSerie(i)}
                stroke="var(--card)"
                strokeWidth={empile ? 2 : 0}
                isAnimationActive={false}
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                shape={((props: any) => {
                  // Pourcentage écrit au centre de la part — seul moyen de
                  // comparer deux parts voisines sans les mesurer à l'œil
                  // (même raisonnement que `DonutChart`). Masqué sous ~18px :
                  // en dessous, le texte ne tiendrait pas dans le segment.
                  const valeur = Math.round(Number(props.value ?? 0));
                  const etiquette = percent && props.height > 18;
                  // Contraste mesuré (colorjs.io) blanc/encre contre les 6
                  // couleurs de `--chart-*`, light ET dark : `--primary-foreground`
                  // convient partout SAUF chart-5 (indice 4) où lui seul
                  // n'atteint que 4,05:1 en sombre — blanc fixe y passe dans
                  // les deux thèmes (4,62 / 6,64) et est donc conservé tel quel.
                  const texte = i % 6 === 4 ? "oklch(1 0 0)" : "var(--primary-foreground)";
                  return (
                    // L'emphase se fait par RETRAIT : la catégorie pointée
                    // garde sa pleine intensité, les autres s'effacent.
                    <g opacity={opaciteSerie(indexActif, props.index)}>
                      <path
                        d={cheminBarre(
                          props.x,
                          props.y,
                          props.width,
                          props.height,
                          // Empilé, seul le segment du HAUT s'arrondit : arrondir
                          // chaque segment creuserait des encoches entre eux et
                          // ferait lire une pile comme des blocs détachés.
                          !empile || i === series.length - 1 ? 4 : 0
                        )}
                        fill={`url(#${idDegrade}-s${i})`}
                      />
                      {empile && (
                        // Le séparateur : sans lui, deux segments de teintes
                        // voisines fusionnent en un seul bloc.
                        <path
                          d={cheminBarre(
                            props.x,
                            props.y,
                            props.width,
                            props.height,
                            !empile || i === series.length - 1 ? 4 : 0
                          )}
                          fill="none"
                          stroke="var(--card)"
                          strokeWidth={2}
                        />
                      )}
                      {etiquette && (
                        <text
                          x={props.x + props.width / 2}
                          y={props.y + props.height / 2}
                          textAnchor="middle"
                          dominantBaseline="central"
                          fill={texte}
                          fontSize={13}
                          fontWeight={700}
                        >
                          {valeur} %
                        </text>
                      )}
                    </g>
                  );
                }) as never}
              />
            ))}
          </RechartsBarChart>
        </ResponsiveContainer>
      )}
    </ChartFrame>
  );
}

import { useEffect, useId, useState, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Table, type TableColumn } from "@registry/aikoz/table/table";

// ─── Vocabulaire des séries ──────────────────────────────────────────────────

/**
 * Six séries, trois canaux redondants chacune, dans un ordre FIXE : la
 * série 1 aura toujours le même trait plein et le même rond, quel que soit
 * le graphique. Une identité qui change d'un écran à l'autre ne s'apprend
 * pas.
 *
 * **Le pointillé n'est pas décoratif — la trame, elle, a été retirée.** Mesuré sur notre
 * palette : la meilleure séparation atteignable entre six séries est de
 * **1,26:1 en clair, 1,30 en sombre** — un ratio de LUMINANCE, pas un écart
 * perceptuel. Elles se confondent donc en niveaux
 * de gris et pour une part des daltonismes. La couleur ne porte pas la
 * distinction — elle la renforce, pour qui la perçoit.
 *
 * **Correction d'une mesure fausse.** Ce commentaire disait que la couleur
 * n'avait « aucun pouvoir distinctif », sur la foi d'un ratio de contraste
 * WCAG entre séries. C'était la mauvaise métrique : le ratio WCAG mesure une
 * LUMINANCE, il sert à lire du texte sur un fond, pas à distinguer deux
 * aplats voisins. La bonne mesure est l'écart perceptuel (ΔE OKLab), évalué
 * en simulant les trois daltonismes.
 *
 * Mesuré ainsi, la palette sépare de **ΔE 0,19 à 0,28** en vision normale
 * comme en protanopie et en deutéranopie — très au-dessus du seuil de ~0,10.
 * La couleur suffit donc, et les trames qui hachuraient les barres ont été
 * retirées : elles alourdissaient la lecture sans rien apporter.
 *
 * **Une exception, assumée :** en tritanopie, bleu et vert virent tous deux au
 * turquoise et l'écart tombe à 0,068. Elle touche une personne sur dix mille,
 * contre près de 8 % des hommes pour la deutéranopie, et le tableau sous le
 * graphique porte la donnée sans dépendre d'aucune couleur.
 *
 * Le POINTILLÉ des courbes reste, lui : deux courbes se superposent là où
 * deux barres ne se touchent que par un bord, et les styles de trait sont la
 * recommandation constante de la littérature (Carbon, Datawrapper).
 *
 * Les couleurs de statut restent exclues — une série qui porte le jaune
 * d'avertissement se lit comme une alerte.
 */
export const SERIES = [
  { trait: undefined, nom: "trait plein" },
  { trait: "8 4", nom: "tirets longs" },
  { trait: "2 3", nom: "pointillé fin" },
  { trait: "12 3 2 3", nom: "tiret-point" },
  { trait: "4 4", nom: "tirets courts" },
  { trait: "1 5", nom: "points espacés" },
] as const;

export const couleurSerie = (i: number) => `var(--chart-${(i % 6) + 1})`;
export const styleSerie = (i: number) => SERIES[i % SERIES.length];

// ─── Survol ───────────────────────────────────────────────────────────────────

export interface ContexteGraphique {
  /** Identifiant unique, dérivé de `useId`. */
  idTrames: string;
  /**
   * Faut-il rendre l'infobulle ? Faux quand le pointeur est ailleurs, et faux
   * aussi après un appui sur Échap — cf. `ChartFrame`.
   */
  infobulleActive: boolean;
  /** Index de la catégorie survolée, ou `null`. Sert à l'emphase. */
  indexActif: number | null;
  /** À brancher sur le graphique recharts pour suivre la catégorie survolée. */
  surSurvol: (etat: { activeTooltipIndex?: number | null } | null) => void;
}

/**
 * Emphase de la valeur survolée — **par retrait, pas par ajout**.
 *
 * L'élément pointé ne change pas : ce sont les autres qui s'effacent à 30 %.
 * C'est le geste de Carbon, et il vaut mieux que ce qu'on avait — un contour
 * `--foreground` de 2px, qui lisait comme une SÉLECTION et non comme un
 * survol, et qui ajoutait un trait là où l'œil cherchait une donnée.
 *
 * **J'avais écarté l'atténuation pour une mauvaise raison** : la crainte que
 * les séries estompées tombent sous les 3:1 de WCAG 1.4.11. Ce seuil vaut
 * pour l'état au repos, celui qui permet d'identifier un composant. Une
 * atténuation de survol est transitoire, réversible au moindre mouvement, et
 * n'enlève aucune information — le tableau porte toutes les valeurs. Carbon,
 * Ant Design et Material appliquent tous ce geste.
 *
 * 30 % est la valeur de Carbon. Plus haut, l'effacement ne se voit pas ;
 * plus bas, les autres séries disparaissent au lieu de passer au second plan.
 */
export const OPACITE_ESTOMPEE = 0.3;

/**
 * Opacité d'une série selon ce qui est survolé. `1` quand rien ne l'est —
 * un graphique au repos ne doit jamais être à demi effacé.
 */
export function opaciteSerie(indexActif: number | null, index: number): number {
  return indexActif === null || indexActif === index ? 1 : OPACITE_ESTOMPEE;
}

export interface LigneInfobulle {
  dataKey?: string | number;
  name?: string;
  value?: string | number;
  color?: string;
}

/**
 * Contenu d'infobulle commun aux trois graphiques.
 *
 * Reprend les tokens de `Tooltip` (`--popover`, `--popover-foreground`,
 * `--border-strong`) : une infobulle est une surface flottante comme une
 * autre, et une inversion figée sur `--foreground` casserait le thème.
 *
 * **Elle n'est jamais la seule source d'une valeur** — le tableau qui suit le
 * graphique les porte toutes. C'est ce qui la rend acceptable alors qu'elle
 * ne s'ouvre qu'à la souris.
 */
export function ChartTooltipContent({
  active,
  label,
  payload,
  formatValue = (v) => String(v),
}: {
  active?: boolean;
  label?: string | number;
  payload?: LigneInfobulle[];
  formatValue?: (v: string | number) => string;
}) {
  if (!active || !payload?.length) return null;
  return (
    <div
      className={cn(
        "rounded-[var(--radius)] border border-[var(--border-strong)] px-3 py-2 shadow-lg",
        "bg-[var(--popover)] text-[var(--popover-foreground)] text-xs leading-snug"
      )}
    >
      {label !== undefined && label !== "" && (
        <p className="m-0 mb-1.5 font-semibold">{label}</p>
      )}
      <ul className="m-0 flex list-none flex-col gap-1 p-0">
        {payload.map((p, i) => (
          <li key={String(p.dataKey ?? i)} className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="inline-block size-2.5 shrink-0 rounded-sm"
              style={{ background: p.color }}
            />
            <span>
              {p.name} : <strong className="tabular-nums">{formatValue(p.value ?? "")}</strong>
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ChartSerie {
  key: string;
  label: string;
}

export interface ChartFrameProps<T> {
  /**
   * Ce que le graphique montre — **obligatoire**. C'est la légende du
   * tableau équivalent, donc le nom accessible de la donnée.
   */
  caption: string;
  /** Phrase de résumé. Complétée automatiquement par le renvoi au tableau. */
  summary: string;
  series: ChartSerie[];
  /** Données brutes, telles qu'elles alimentent le tableau équivalent. */
  data: T[];
  /** Colonnes du tableau équivalent. */
  columns: TableColumn<T>[];
  getRowKey: (row: T, index: number) => string;
  /** Colonne qui NOMME la ligne — cf. `Table`. */
  rowHeaderKey?: string;
  /** Le graphique lui-même. Voir `ContexteGraphique`. */
  children: (ctx: ContexteGraphique) => ReactNode;
  height?: number;
  /** Masque la légende, quand le graphique étiquette déjà ses parts. */
  hideLegend?: boolean;
  /** Aplats plutôt que tracés : la légende montre des pastilles pleines. */
  legendStyle?: "trait" | "aplat";
  /**
   * Comment le tableau équivalent cohabite avec le graphique.
   *
   * `"bascule"` (défaut) — deux vues du MÊME bloc, commutées par un
   * sélecteur posé sur la ligne du titre. La zone garde exactement la même
   * hauteur, donc afficher les valeurs ne déplace rien sur la page.
   *
   * `"dessous"` — le tableau est rendu sous le graphique, toujours visible.
   * Pour les pages où il EST le contenu, comme le forage territorial.
   */
  tableau?: "bascule" | "dessous";
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Coque commune à tous les graphiques.
 *
 * **Pas de story pour ce fichier, et c'est délibéré** : il ne rend rien seul.
 * Ce qu'il garantit se vérifie dans les stories de `LineChart`, `BarChart` et
 * `DonutChart`, qui l'utilisent. Une story de remplissage donnerait l'illusion
 * d'une couverture sans rien tester de plus.
 *
 * Elle existe pour que le contrat d'accessibilité soit tenu **par
 * construction** plutôt que répété — et oublié une fois sur cinq. Tout
 * graphique du système passe par elle, et en hérite :
 *
 * 1. **Le graphique est masqué, le tableau EST le contenu.** Un SVG de
 *    données ne se lit pas : on ne peut ni comparer deux valeurs, ni en
 *    retrouver une, ni copier quoi que ce soit. Le `aria-label` donne le
 *    résumé, le tableau donne la donnée — et il réutilise `Table`, donc ses
 *    en-têtes de ligne et de colonne.
 * 2. **La légende arrive APRÈS le graphique.** Placée avant, elle
 *    s'interposait entre le titre et la donnée : l'œil devait traverser une
 *    liste de noms pour atteindre ce qu'il venait voir. En dessous, elle ne
 *    sert qu'à ceux qui en ont besoin, au moment où une courbe les
 *    interroge. Et `LineChart` la masque carrément quand ses courbes portent
 *    déjà leur nom au bout du tracé.
 * 3. **Trois canaux par série**, jamais la couleur seule (WCAG 1.4.1).
 * 4. **Aucune animation** (WCAG 2.3.3).
 *
 * Le tableau est replié dans un `details` par défaut : présent dans le
 * document et lu, sans occuper la place.
 */
export function ChartFrame<T>({
  caption,
  summary,
  series,
  data,
  columns,
  getRowKey,
  rowHeaderKey,
  children,
  height = 280,
  hideLegend = false,
  legendStyle = "trait",
  tableau = "bascule",
  className,
}: ChartFrameProps<T>) {
  const uid = useId().replace(/:/g, "");
  const [vue, setVue] = useState<"graphique" | "tableau">("graphique");

  // ── Survol : l'infobulle et l'emphase ────────────────────────────────────
  //
  // WCAG 1.4.13 — un contenu qui apparaît au survol doit pouvoir être ÉCARTÉ
  // sans déplacer le pointeur. Recharts ne le prévoit pas : son infobulle
  // suit la souris et rien ne la referme. Échap la retire donc ici, et elle
  // ne revient qu'après être sorti puis rentré dans le graphique — c'est le
  // comportement attendu par le critère, pas une bascule permanente.
  const [survol, setSurvol] = useState(false);
  const [ecartee, setEcartee] = useState(false);
  const [indexActif, setIndexActif] = useState<number | null>(null);

  useEffect(() => {
    if (!survol || ecartee) return;
    const auClavier = (e: KeyboardEvent) => {
      if (e.key === "Escape") setEcartee(true);
    };
    document.addEventListener("keydown", auClavier);
    return () => document.removeEventListener("keydown", auClavier);
  }, [survol, ecartee]);

  const tableauRendu = (
    <Table
      caption={caption}
      captionHidden
      columns={columns}
      rows={data}
      getRowKey={getRowKey}
      rowHeaderKey={rowHeaderKey}
      density="compact"
    />
  );

  // ── Graphique OU tableau, jamais l'un qui pousse l'autre ────────────────
  //
  // Le tableau était replié dans un `details` sous le graphique. Mesuré sur
  // le tableau de bord : l'ouvrir faisait passer le bloc de 378 à 650 px
  // (+72 %) et décalait de 272 px tout ce qui suit. Sur une grille à deux
  // colonnes, la rangée se désaligne en plus.
  //
  // Deux VUES du même bloc à la place, commutées sur la ligne du titre. La
  // zone garde la hauteur du graphique, le tableau défile à l'intérieur :
  // afficher les valeurs ne déplace plus rien.
  //
  // Et non, l'export ne remplace pas ce tableau. C'est un autre parcours,
  // qui produit un fichier : WCAG 1.1.1 demande l'équivalent DANS la page.
  // Le SVG est `aria-hidden` — sans ce tableau, les valeurs exactes
  // n'existent nulle part pour qui ne voit pas le dessin.
  const bascule = tableau === "bascule";
  const onglet = (cle: "graphique" | "tableau", libelle: string) => (
    <button
      type="button"
      role="tab"
      id={`${uid}-onglet-${cle}`}
      aria-selected={vue === cle}
      aria-controls={`${uid}-vue`}
      // Un seul arrêt de tabulation pour le groupe, les flèches font le
      // reste : c'est le patron ARIA des onglets.
      tabIndex={vue === cle ? 0 : -1}
      onClick={() => setVue(cle)}
      onKeyDown={(e) => {
        if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
        e.preventDefault();
        setVue(cle === "graphique" ? "tableau" : "graphique");
      }}
      className={cn(
        "min-h-8 rounded-full px-2.5 text-xs transition-colors",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
        "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--card)]",
        vue === cle
          ? "bg-muted font-medium text-foreground"
          : "text-muted-foreground hover:text-foreground",
      )}
    >
      {libelle}
    </button>
  );

  return (
    <figure className={cn("m-0 flex flex-col gap-4", className)}>
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1">
        <figcaption className="text-sm font-medium text-foreground">
          {caption}
        </figcaption>
        {bascule && (
          <div
            role="tablist"
            aria-label={`Affichage de « ${caption} »`}
            className="flex shrink-0 items-center gap-0.5 rounded-full bg-[color-mix(in_oklch,var(--muted),transparent_55%)] p-0.5"
          >
            {onglet("graphique", "Graphique")}
            {onglet("tableau", "Tableau")}
          </div>
        )}
      </div>

      <div
        id={bascule ? `${uid}-vue` : undefined}
        role={bascule ? "tabpanel" : undefined}
        aria-labelledby={bascule ? `${uid}-onglet-${vue}` : undefined}
        // La hauteur est portée ICI, pas par le graphique : c'est elle qui
        // garantit que la bascule ne déplace rien.
        style={{ height }}
        className="w-full"
      >
        {bascule && vue === "tableau" ? (
          <div className="h-full overflow-auto">{tableauRendu}</div>
        ) : (
          <div
            role="img"
            aria-label={
              bascule
                ? `${summary} Les valeurs exactes sont dans la vue « Tableau ».`
                : `${summary} Les valeurs exactes sont dans le tableau qui suit.`
            }
            className="h-full w-full"
          >
            {/*
              Le SVG est masqué, et ce n'est pas une redondance avec le
              `role="img"` du parent. Recharts pose `role="img"` sur CHAQUE
              secteur et chaque tracé, sans nom accessible : axe y voit autant
              d'images sans alternative. Le parent porte le nom, le tableau
              porte la donnée.
            */}
            <div
              aria-hidden="true"
              className="h-full w-full"
              onMouseEnter={() => setSurvol(true)}
              onMouseLeave={() => {
                setSurvol(false);
                setEcartee(false);
                setIndexActif(null);
              }}
            >
              {children({
                idTrames: uid,
                infobulleActive: survol && !ecartee,
                indexActif,
                surSurvol: (etat) =>
                  setIndexActif(etat?.activeTooltipIndex ?? null),
              })}
            </div>
          </div>
        )}
      </div>

      {/* La légende SOUS le graphique, pas au-dessus.
          Placée avant, elle s'interpose entre le titre et la donnée : l'œil
          doit traverser une liste de noms pour atteindre ce qu'il est venu
          voir. Placée après, elle ne sert qu'à ceux qui en ont besoin, au
          moment où ils en ont besoin — quand une courbe les interroge.

          Elle reste affichée dans la vue tableau : la retirer ferait
          exactement le saut de mise en page qu'on vient de supprimer, et
          elle reste juste, les colonnes portant les mêmes séries. */}
      {!hideLegend && <ChartLegend series={series} style={legendStyle} />}

      {!bascule && tableauRendu}
    </figure>
  );
}

// ─── Légende ──────────────────────────────────────────────────────────────────

export interface ChartLegendProps {
  series: ChartSerie[];
  /** `trait` pour les courbes, `aplat` pour les barres et les parts. */
  style?: "trait" | "aplat";
  className?: string;
}

/**
 * Légende d'un graphique.
 *
 * Chaque entrée montre les canaux tels qu'on les reconnaîtra dans le
 * graphique — la couleur et, pour les courbes, le tracé. Une légende qui
 * montrerait autre chose que le graphique ne sert à rien.
 *
 * Le nom du canal est aussi écrit en `sr-only`. Sans lui, la légende lue à
 * voix haute donne une liste de noms sans clé de lecture.
 */
export function ChartLegend({ series, style = "trait", className }: ChartLegendProps) {
  return (
    <ul className={cn("flex flex-wrap gap-x-5 gap-y-2 list-none m-0 p-0", className)}>
      {series.map((s, i) => {
        const v = styleSerie(i);
        const c = couleurSerie(i);
        return (
          <li key={s.key} className="inline-flex items-center gap-2 text-sm">
            <svg
              aria-hidden="true"
              focusable="false"
              viewBox={style === "trait" ? "0 0 28 12" : "0 0 36 14"}
              className={cn("shrink-0", style === "trait" ? "h-3 w-7" : "h-3.5 w-9")}
              fill="none"
            >
              {style === "trait" ? (
                <>
                  <line x1="0" y1="6" x2="28" y2="6" stroke={c} strokeWidth="2" strokeDasharray={v.trait} />
                  <circle cx="14" cy="6" r="3.5" fill={c} />
                </>
              ) : (
                // Pastille pleine. Elle montre exactement ce que montre le
                // graphique — c'est toute la fonction d'une légende.
                <rect x="0" y="0" width="36" height="14" rx="3" fill={c} />
              )}
            </svg>
            <span className="text-foreground">{s.label}</span>
            <span className="sr-only">
              ({style === "trait" ? v.nom : "aplat"})
            </span>
          </li>
        );
      })}
    </ul>
  );
}

import { type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Skeleton } from "@registry/aikoz/skeleton/skeleton";

// ─── Types ────────────────────────────────────────────────────────────────────

export type SortDirection = "asc" | "desc";

export interface TableSort {
  key: string;
  direction: SortDirection;
}

export interface TableColumn<T> {
  key: string;
  /** En-tête de colonne. Court : il est relu à chaque cellule par un
   *  lecteur d'écran en mode tableau. */
  header: string;
  /** Rendu de la cellule. Par défaut, la valeur brute de `row[key]`. */
  cell?: (row: T) => ReactNode;
  /**
   * Colonne de nombres : alignée à droite et en chiffres tabulaires, pour
   * que les unités s'empilent et que la comparaison verticale soit possible.
   */
  numeric?: boolean;
  /** Rend l'en-tête cliquable et pose `aria-sort`. */
  sortable?: boolean;
  /** Largeur CSS imposée — `"12rem"`, `"25%"`. */
  width?: string;
}

export interface TableProps<T> {
  /**
   * Ce que le tableau contient — **obligatoire**. C'est son nom accessible,
   * et c'est ce qui permet de savoir dans quel tableau on est quand une page
   * en porte plusieurs. Rendu en `<caption>`, donc lié nativement, sans
   * `aria-label` à maintenir en double.
   */
  caption: string;
  /** Masque la légende visuellement. Elle reste lue. */
  captionHidden?: boolean;
  columns: TableColumn<T>[];
  rows: T[];
  getRowKey: (row: T, index: number) => string;
  /**
   * Colonne qui NOMME la ligne — le libellé d'agence, le nom d'aéroport.
   * Elle est rendue en `<th scope="row">`, ce qui fait annoncer « Amsterdam,
   * taux de réponse, 94 % » au lieu de « 94 % » tout court quand on navigue
   * de cellule en cellule.
   */
  rowHeaderKey?: string;
  sort?: TableSort;
  onSortChange?: (sort: TableSort) => void;
  /** Affiche des lignes d'attente à la place des données. */
  loading?: boolean;
  /** Nombre de lignes d'attente. */
  loadingRows?: number;
  /** Rendu quand `rows` est vide — un `EmptyState`, en général. */
  empty?: ReactNode;
  density?: "compact" | "default";
  className?: string;
}

// ─── Sous-éléments ────────────────────────────────────────────────────────────

/** Deux chevrons superposés : l'actif est plein, l'autre effacé. La direction
 *  ne tient donc pas à la seule couleur — la FORME diffère. */
function Fleche({ direction }: { direction?: SortDirection }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 10 12"
      className="size-2.5 shrink-0"
      fill="currentColor"
    >
      <path d="M5 0.5 8 4H2z" opacity={direction === "asc" ? 1 : 0.3} />
      <path d="M5 11.5 2 8h6z" opacity={direction === "desc" ? 1 : 0.3} />
    </svg>
  );
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Tableau de données.
 *
 * Un vrai `<table>`, pas une grille CSS de `div`. Ce n'est pas une question
 * de goût : les balises de tableau portent des RELATIONS que rien ne remplace.
 * Un lecteur d'écran en mode tableau annonce, à chaque déplacement, l'en-tête
 * de colonne et l'en-tête de ligne de la cellule où il arrive — « Amsterdam,
 * taux de réponse, 94 % ». Une grille de `div` ne donne que « 94 % », et
 * l'utilisateur doit compter les colonnes de tête.
 *
 * Trois choses que ce composant fait et qu'on oublie presque toujours :
 *
 * 1. **`<caption>` plutôt qu'`aria-label`.** La légende est visible par
 *    défaut, liée nativement, et ne peut pas se désynchroniser d'un titre
 *    voisin. `captionHidden` la masque quand la mise en page l'exige.
 * 2. **Le conteneur qui défile est focusable.** Un tableau plus large que son
 *    cadre défile horizontalement ; sans `tabIndex={0}` sur le conteneur, la
 *    partie hors champ est inatteignable au clavier — on ne peut pas faire
 *    défiler ce sur quoi on ne peut pas se poser. Il porte `role="region"` et
 *    un nom, sinon ce nouvel arrêt de tabulation serait muet.
 * 3. **Le tri s'annonce par `aria-sort` sur le `<th>`**, pas par une icône.
 *    Le bouton reste dans l'en-tête plutôt que d'être l'en-tête lui-même :
 *    un `<th>` cliquable sans bouton n'est ni focusable ni actionnable au
 *    clavier.
 */
export function Table<T>({
  caption,
  captionHidden = false,
  columns,
  rows,
  getRowKey,
  rowHeaderKey,
  sort,
  onSortChange,
  loading = false,
  loadingRows = 5,
  empty,
  density = "default",
  className,
}: TableProps<T>) {
  const cellule = density === "compact" ? "px-3 py-2" : "px-4 py-3";

  function trier(key: string) {
    const direction: SortDirection =
      sort?.key === key && sort.direction === "asc" ? "desc" : "asc";
    onSortChange?.({ key, direction });
  }

  const vide = !loading && rows.length === 0;

  return (
    <div
      // `role="region"` + nom + `tabIndex` : les trois vont ensemble. Sans le
      // nom, un lecteur d'écran annonce « région » sans dire laquelle ; sans
      // `tabIndex`, le débordement horizontal est inatteignable au clavier.
      role="region"
      aria-label={caption}
      tabIndex={0}
      // `aria-busy` porté UNE fois par le conteneur, pas par chaque squelette :
      // c'est le tableau qui charge, pas quatorze rectangles.
      aria-busy={loading || undefined}
      className={cn(
        "w-full overflow-x-auto rounded-[var(--radius)] border border-border bg-card",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
        className
      )}
    >
      <table className="w-full border-collapse text-sm">
        <caption
          className={cn(
            "text-left text-sm text-muted-foreground",
            captionHidden ? "sr-only" : cellule
          )}
        >
          {caption}
        </caption>

        <thead>
          <tr className="border-b border-border">
            {columns.map((c) => {
              const actif = sort?.key === c.key;
              return (
                <th
                  key={c.key}
                  scope="col"
                  // `aria-sort` ne va que sur la colonne triée : le poser à
                  // « none » partout ferait annoncer « non trié » sur chaque
                  // en-tête, à chaque parcours.
                  aria-sort={
                    actif
                      ? sort.direction === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  style={c.width ? { width: c.width } : undefined}
                  className={cn(
                    cellule,
                    "font-semibold text-foreground",
                    c.numeric ? "text-right" : "text-left"
                  )}
                >
                  {c.sortable && onSortChange ? (
                    <button
                      type="button"
                      onClick={() => trier(c.key)}
                      className={cn(
                        "inline-flex items-center gap-1.5 min-h-6 rounded-[calc(var(--radius)/2)]",
                        "font-semibold hover:text-[var(--secondary)]",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                        c.numeric && "flex-row-reverse"
                      )}
                    >
                      {c.header}
                      <Fleche direction={actif ? sort.direction : undefined} />
                    </button>
                  ) : (
                    c.header
                  )}
                </th>
              );
            })}
          </tr>
        </thead>

        <tbody>
          {loading &&
            Array.from({ length: loadingRows }, (_, i) => (
              <tr key={`attente-${i}`} className="border-b border-border last:border-0">
                {columns.map((c) => (
                  <td key={c.key} className={cellule}>
                    <Skeleton shape="text" className={c.numeric ? "w-12 ml-auto" : "w-4/5"} />
                  </td>
                ))}
              </tr>
            ))}

          {vide && (
            <tr>
              {/* `colSpan` sur toute la largeur : une cellule vide par colonne
                  ferait annoncer autant de cellules vides. */}
              <td colSpan={columns.length} className="p-0">
                {empty}
              </td>
            </tr>
          )}

          {!loading &&
            rows.map((row, i) => (
              <tr
                key={getRowKey(row, i)}
                className="border-b border-border last:border-0 hover:bg-[var(--surface-hover)]"
              >
                {columns.map((c) => {
                  const contenu = c.cell
                    ? c.cell(row)
                    : ((row as Record<string, unknown>)[c.key] as ReactNode);
                  const classes = cn(
                    cellule,
                    // Chiffres tabulaires : sans eux, les colonnes de nombres
                    // ne s'alignent pas verticalement et la comparaison d'une
                    // ligne à l'autre demande de relire chiffre par chiffre.
                    c.numeric ? "text-right tabular-nums" : "text-left"
                  );
                  return c.key === rowHeaderKey ? (
                    <th
                      key={c.key}
                      scope="row"
                      className={cn(classes, "font-medium text-foreground")}
                    >
                      {contenu}
                    </th>
                  ) : (
                    <td key={c.key} className={cn(classes, "text-foreground")}>
                      {contenu}
                    </td>
                  );
                })}
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

import { type HTMLAttributes } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {
  /** Forme du bloc. `text` prend la hauteur d'une ligne, `circle` un rond. */
  shape?: "block" | "text" | "circle";
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Bloc d'attente.
 *
 * **Il est intégralement invisible aux technologies d'assistance**, et ce
 * n'est pas un oubli : annoncer « rectangle gris » quatorze fois ne renseigne
 * personne. C'est au CONTENEUR de dire qu'un chargement est en cours, une
 * fois, par `aria-busy="true"` — et de dire ce qui a chargé une fois fini,
 * par une région live. Un squelette qui parle est un squelette qui bavarde.
 *
 * L'animation est coupée par `motion-reduce` : une pulsation permanente sur
 * toute une page déclenche des malaises chez les personnes sensibles au
 * mouvement (WCAG 2.3.3). Sans elle le bloc reste parfaitement lisible — il
 * n'a jamais porté d'information dans son mouvement.
 *
 * `--track` et non `--muted` : en thème sombre ce dernier vaut exactement
 * `--card`, le squelette y serait strictement invisible. C'est le même piège
 * que la piste de `ProgressBar`.
 */
export function Skeleton({ shape = "block", className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "bg-[var(--track)] motion-safe:animate-pulse",
        shape === "circle" && "rounded-full aspect-square",
        shape === "text" && "h-4 rounded-[calc(var(--radius)/2)]",
        shape === "block" && "rounded-[var(--radius)]",
        className
      )}
      {...props}
    />
  );
}

export interface SkeletonTextProps {
  /** Nombre de lignes. */
  lines?: number;
  className?: string;
}

/**
 * Paragraphe d'attente. La dernière ligne est plus courte — un bloc de
 * lignes toutes égales ne ressemble à aucun texte réel, et l'œil met plus
 * longtemps à comprendre qu'il regarde une attente.
 */
export function SkeletonText({ lines = 3, className }: SkeletonTextProps) {
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {Array.from({ length: lines }, (_, i) => (
        <Skeleton key={i} shape="text" className={i === lines - 1 ? "w-3/5" : "w-full"} />
      ))}
    </div>
  );
}

import { forwardRef, type ButtonHTMLAttributes } from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2",
    "rounded-full font-medium",
    // Pas de `whitespace-nowrap` : avec lui, un libellé long sortait du
    // conteneur et se faisait rogner — un bouton qui découpe son propre
    // libellé est cassé, et sur mobile le texte disparaissait purement.
    // Le repli gracieux est le retour à la ligne : la pastille s'allonge,
    // ce qui signale au passage qu'il faut raccourcir l'intitulé.
    "max-w-full text-center text-balance",
    "transition-colors duration-150",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
    "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
    "disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed",
  ],
  {
    variants: {
      variant: {
        default: [
          "bg-[var(--primary)] text-[var(--primary-foreground)]",
          "hover:bg-[color-mix(in_oklch,var(--primary),transparent_10%)] active:bg-[color-mix(in_oklch,var(--primary),transparent_20%)]",
        ],
        secondary: [
          "bg-[var(--secondary)] text-[var(--secondary-foreground)]",
          "hover:bg-[color-mix(in_oklch,var(--secondary),transparent_10%)] active:bg-[color-mix(in_oklch,var(--secondary),transparent_20%)]",
        ],
        // Le survol de ces deux variantes est porté par la BORDURE, pas par une
        // teinte. Mesuré : un voile d'accent à 12 % donne 1,025:1 sur fond
        // clair — invisible. Monter l'opacité n'y change rien (1,073 à 40 %) :
        // l'aquamarine a presque la même luminance que le fond clair, on
        // déplace la teinte sans déplacer la clarté. La bordure forte, elle,
        // tient 4,07 à 4,58:1 selon le thème.
        outline: [
          "border border-[var(--border)] bg-transparent text-[var(--foreground)]",
          "hover:border-[var(--border-strong)] hover:bg-[var(--surface-hover)]",
          "active:bg-[var(--surface-active,var(--surface-hover))]",
        ],
        ghost: [
          // Bordure transparente au repos : elle apparaît au survol sans
          // décaler la mise en page d'un pixel.
          "border border-transparent bg-transparent text-[var(--foreground)]",
          "hover:border-[var(--border-strong)] hover:bg-[var(--surface-hover)]",
          "active:bg-[var(--surface-active,var(--surface-hover))]",
        ],
      },
      size: {
        sm: "min-h-9 px-4 py-2 text-sm",
        md: "min-h-11 px-6 py-2.5 text-sm",
        lg: "min-h-12 px-8 py-3 text-base",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  }
);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

// ─── Component ────────────────────────────────────────────────────────────────

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, type, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        ref={ref}
        className={cn(buttonVariants({ variant, size }), className)}
        /* Sans type explicite, un <button> dans un <form> vaut type="submit"
           et soumet le formulaire au moindre clic. Le défaut sûr est "button" ;
           un bouton de soumission le déclare. Ne s'applique pas à asChild, où
           l'élément rendu n'est pas forcément un bouton. */
        {...(asChild ? {} : { type: type ?? "button" })}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { buttonVariants };

import { type ElementType, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface EmptyStateProps {
  /**
   * Ce qu'il n'y a pas, dit en clair : « Aucun avis sur cette période ».
   * Pas « Rien à afficher », qui ne dit ni quoi ni pourquoi.
   */
  title: string;
  /**
   * Élément rendu pour le titre. `p` par défaut, **volontairement** : le
   * niveau de titre dépend du plan de la page, pas du composant — même
   * raison que l'absence de `CardTitle` dans `Card`. Passer `h2`/`h3` quand
   * l'état vide remplace une région qui portait déjà un titre de ce rang.
   */
  titleAs?: "p" | "h2" | "h3" | "h4";
  /**
   * Ce qu'on peut faire pour y remédier. La règle : un état vide qui
   * n'indique pas la sortie est un cul-de-sac. « Élargissez la période ou
   * retirez le filtre par source. »
   */
  description?: string;
  /** Illustration ou icône. Décorative : le texte porte tout le sens. */
  icon?: ReactNode;
  /** Action principale — un `Button`, en général. */
  action?: ReactNode;
  /** Action secondaire, en retrait. */
  secondaryAction?: ReactNode;
  /**
   * `default` — un vide normal, attendu : aucun résultat sur ce filtre.
   * `error` — un vide subi : le chargement a échoué. Le ton change le
   * cadre, jamais la présence du texte.
   */
  tone?: "default" | "error";
  density?: "compact" | "default";
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * État vide.
 *
 * Trois choses le distinguent d'un simple message centré :
 *
 * 1. **Il nomme ce qui manque**, pas le fait qu'il manque quelque chose.
 *    « Aucun avis sur cette période » et non « Aucune donnée ».
 * 2. **Il indique la sortie.** Un état vide sans action ni consigne est un
 *    cul-de-sac : l'utilisateur voit que rien ne s'affiche, sans savoir si
 *    c'est normal, si ça va arriver, ou s'il a mal réglé quelque chose.
 * 3. **Il ne parle pas deux fois.** L'icône est décorative ; le ton `error`
 *    ne se lit pas à la seule couleur du cadre, il se lit dans le texte —
 *    ce que WCAG 1.4.1 exige et qu'un liseré rouge muet ne satisfait pas.
 *
 * Le composant n'annonce rien de lui-même. Quand il REMPLACE un contenu qui
 * était là — après un filtre, après un rechargement — c'est au conteneur de
 * poser la région live : lui seul sait si l'apparition est un événement ou
 * l'état initial de la page.
 */
export function EmptyState({
  title,
  titleAs = "p",
  description,
  icon,
  action,
  secondaryAction,
  tone = "default",
  density = "default",
  className,
}: EmptyStateProps) {
  const Titre = titleAs as ElementType;

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center text-center",
        "rounded-[var(--radius)] border",
        density === "compact" ? "gap-2 p-6" : "gap-3 p-10",
        tone === "error"
          // Le fond pâle est DÉCORATIF — mesuré à 1,10:1 sur la carte en
          // clair, 1,09 en sombre : c'est ce qu'on attend d'un « subtle ».
          // L'état d'erreur est porté par le trait ET par le texte, jamais
          // par cette teinte (WCAG 1.4.1).
          ? "border-[var(--destructive-text)] bg-[var(--error-subtle)]"
          : "border-dashed border-border bg-[var(--card)]",
        className
      )}
    >
      {icon && (
        <span aria-hidden="true" className="text-muted-foreground [&>svg]:size-8">
          {icon}
        </span>
      )}

      <Titre
        className={cn(
          "m-0 font-semibold text-foreground",
          density === "compact" ? "text-sm" : "text-base"
        )}
      >
        {title}
      </Titre>

      {description && (
        <p className="m-0 max-w-prose text-sm text-muted-foreground text-balance">
          {description}
        </p>
      )}

      {(action || secondaryAction) && (
        <div className="flex flex-wrap items-center justify-center gap-3 pt-1">
          {action}
          {secondaryAction}
        </div>
      )}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
